local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local K={242,235,35,150,231,130,246,6,97,14,126,5,72,151,167,136,67,212,3,135,204,4,108,215,213,39,180,82,64,228,30,120}
local P=""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""
local S0=12
local function bx(a,b)
 local r=0
 local m=1
 while a>0 or b>0 do
  local aa=a%2
  local bb=b%2
  if aa~=bb then r=r+m end
  a=math.floor(a/2)
  b=math.floor(b/2)
  m=m*2
 end
 return r
end
local function D(s)
 local o={}
 local n=0
 local bits=0
 for i=1,#s do
  local c=s:sub(i,i)
  if c~="=" then
   local v=B:find(c,1,true)
   if v then
    v=v-1
    n=n*64+v
    bits=bits+6
    if bits>=8 then
     bits=bits-8
     o[#o+1]=string.char(math.floor(n/2^bits)%256)
     n=n%2^bits
    end
   end
  end
 end
 return table.concat(o)
end
local C=D(P)
local O={}
local S=S0
for i=1,#C do
 local v=string.byte(C,i)
 local k=K[((i-1)%#K)+1]
 local b
 if bit32 and bit32.bxor then
  b=bit32.bxor(v,k,S)
 else
  b=bx(bx(v,k),S)
 end
 O[#O+1]=string.char(b)
 S=(S+v+k+((i-1)%256))%256
end
local F=table.concat(O)
local L=loadstring or load
assert(L,"loadstring is unavailable")
local f,e=L(F,"@LUNAR_Hub_LootToForge")
assert(f,e)
return f()
